# -*- coding: utf-8 -*-
S = "полный обзор задач 9 класса (очередь G9–G11), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G9_TB_25_476_2", r"в условии потеряна дробная часть: дистракторы и ключ соответствуют уравнению $\frac xy-\frac yx=2{,}1$ (при $(5;2)$: $2{,}5-0{,}4=2{,}1$; при $(2;-5)$: $-0{,}4+2{,}5=2{,}1$), а для «$=2$» система имеет только иррациональные решения ($x\approx\pm4{,}98$, $y\approx\pm2{,}06$ и т. д.)",
  q=r"Найдите все решения системы уравнений: б) $\dfrac{x}{y} - \dfrac{y}{x} = 2{,}1$, $x^{2} + y^{2} = 29$")
E("G9_TB_26_311_1", r"$\cos630^{\circ}=\cos270^{\circ}=0$; $\sin1470^{\circ}=\sin30^{\circ}=\frac12$; $\operatorname{ctg}1125^{\circ}=\operatorname{ctg}45^{\circ}=1$; значение $0-\frac12-1=-\frac32$. В ключе стояло $-1$",
  k=r"$-1{,}5$",
  dnew={0: (r"$-1$", r"Ученик верно привёл углы к $270^{\circ}$, $30^{\circ}$, $45^{\circ}$, но вместо $0-0{,}5-1$ записал $0-0{,}5-0{,}5$ (принял $\operatorname{ctg}45^{\circ}=0{,}5$)."),
        1: (r"$-0{,}5$", r"Ученик забыл вычесть котангенс: $\cos630^{\circ}-\sin1470^{\circ}=0-0{,}5=-0{,}5$, а затем ещё $\operatorname{ctg}1125^{\circ}=1$."),
        2: (r"$1{,}5$", r"Ученик верно нашёл значения $0$, $0{,}5$, $1$, но потерял знаки при вычитании: вычислил $0+0{,}5+1$ вместо $0-0{,}5-1$.")})
